window.AUTH=window.AUTH||{};window.AUTH["17-1678"]={"d":"17-1678","id":"2019/17-1678","n":"Hernandez v. Mesa","briefs":[{"k":"petitioner","label":"Brief of petitioners Jesus C. Hernández, et al.","date":"2019-08-02","url":"https://www.supremecourt.gov/DocketPDF/17/17-1678/111061/20190802111907651_17-1678%20ts%20PDFA.pdf","side":"pet","n":57},{"k":"respondent","label":"Brief of respondent Jesus Mesa, Jr.","date":"2019-09-23","url":"https://www.supremecourt.gov/DocketPDF/17/17-1678/116667/20190923131104744_Response%20Brief.pdf","side":"res","n":45},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-09-30","url":"https://www.supremecourt.gov/DocketPDF/17/17-1678/117525/20190930171236675_17-1678bsacUnitedStates.pdf","side":"us","n":70},{"k":"reply","label":"Reply of petitioners Jesus C. Hernández, et al.","date":"2019-10-23","url":"https://www.supremecourt.gov/DocketPDF/17/17-1678/119902/20191023085321619_Hernandez%20II%20--%20Reply%20Brief.pdf","side":"pet","n":49}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/589US1PP_Web.pdf#page=134","tr":true,"items":[{"t":"case","label":"Al Shimari v. CACI Premier Tech., Inc.","cite":"758 F.3d 516","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/758/516/","by":{"0":"32"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr.","cite":"135 S. Ct. 1378","y":2015,"id":"2014/14-15","sc":1,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"0":"16","3":"22"}},{"t":"case","label":"Barr v. Matteo","cite":"360 U.S. 564","y":1959,"id":"1958/350","sc":1,"sum":"Justice John M. Harlan delivered the judgement of the court, reversing the court of appeals. The plurality argued that the statements from the press release were absolutely privileged. Justice Felix Frankfurter, Justice Tom C. Clark, and Justice Charles E. Whittaker joined in the plurality.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Bartlett ex rel. Neuman v. Bowen","cite":"816 F.2d 695","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/816/695/","by":{"0":"42"}},{"t":"case","label":"Bates v. Clark","cite":"95 U.S. 204","y":1877,"id":"scdb/1877-066","sc":1,"by":{"0":"14"}},{"t":"case","label":"Belknap v. Schild","cite":"161 U.S. 10","y":1896,"id":"scdb/1895-108","sc":1,"sum":"The United States have no right to use a patented invention without license of the patentee or making compensation to him.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Bell v. Hood","cite":"327 U.S. 678","y":1946,"id":"scdb/1945-042","sc":1,"sum":"1. Where the complaint seeks recovery squarely on the ground of violation of plaintiffs' rights under the Fourth and Fifth Amendments, a federal district court has jurisdiction of a suit against agents of the Federal Government to recover damages in excess of $3,000 alleged to have been suffered by the plaintiffs as a result of such violations-even though neither the Constitution nor the Congress has provided for …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 17"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of the Fed. Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"op":128,"ar":48,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"1, 2, 8, 10, 12, 13","3":"1, 17, 23"}},{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"op":1,"ar":2,"sum":"The Court held that the Military Commissions Act of 2006 violated the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"32","1":"14","3":"4, 20"}},{"t":"case","label":"Bowen v. Mich. Acad. of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Browder v. City of Albuquerque","cite":"787 F.3d 1076","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/787/1076/","by":{"0":"42"}},{"t":"case","label":"Carlson v. Green","cite":"446 U.S. 14","y":1980,"id":"1979/78-1261","sc":1,"op":8,"ar":2,"sum":"Respondent brought suit in Federal District Court in Indiana on behalf of her deceased son's estate, alleging that her son while a prisoner in a federal prison in Indiana suffered personal injuries from which he died because petitioner prison officials violated, inter alia, his Eighth Amendment rights by failing to give him proper medical attention. Asserting jurisdiction under 28 U. S. C. § 1331 (a), respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20","1":"6, 12","2":"11","3":"1, 11"}},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"sum":"In a 5-to-4 decision, the Court held that federal courts were without jurisdiction to entertain Lyons' claim for injunctive relief.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Claflin v. Houseman","cite":"93 U.S. 130","y":1876,"id":"scdb/1876-027","sc":1,"sum":"This action was brought in May, 1872, in the New York Supreme Court, county of Kings, by Julius Houseman, as assignee in bankruptcy of Comstock and Young, against Horace B. Clafiin, under the thirty-fifth section of the Bankrupt Act, to recover the sum of $1,935.57, with interest, being the amount collected by Clafiin on a judgment against the bankrupts, recovered within four months before the commencement' of …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Corr. Servs. Corp. v. Malesko","cite":"534 U.S. 61","y":2001,"id":"2001/00-860","sc":1,"op":9,"sum":"The Court held that Bivens' limited holding may not be extended to confer a right of action for damages against private entities acting under color of federal law. The Court reasoned that the threat of suit against an individual's employer was not the kind of deterrence contemplated by the Bivens decision.","sumSrc":"Oyez","by":{"0":"passim","1":"7, 8, 11, 25","2":"10, 11, 12, 13","3":"1, 5, 18"}},{"t":"case","label":"Davis v. Passman","cite":"442 U.S. 228","y":1979,"id":"1978/78-5072","sc":1,"op":4,"sum":"Relying on Bivens v. Six Unknown Federal Narcotics Agents (1971) and Butz v. Economou (1978), the Court reversed the lower court's conclusions. Both cases affirmed a citizen's right to bring suit against federal officers for constitutional violations. In this case, Passman violated Davis's rights through sexual discrimination.","sumSrc":"Oyez","by":{"0":"23","1":"6, 25","2":"11"}},{"t":"case","label":"De La Paz v. Coy","cite":"786 F.3d 367","y":2015,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/786/367/","by":{"0":"28"}},{"t":"case","label":"Def. Distrib. v. U.S. Dep’t of State","cite":"838 F.3d 451","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/838/451/","by":{"0":"30"}},{"t":"case","label":"Delgado v. Zaragoza","cite":"267 F. Supp. 3d 892","y":2016,"court":"W.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/267/892/","by":{"0":"19","3":"18"}},{"t":"case","label":"Dow Chem. Co. v. Castro Alfaro","cite":"786 S.W.2d 674","y":1990,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/786/674/","by":{"0":"19"}},{"t":"case","label":"Erie R.R. Co. v. Tompkins","cite":"304 U.S. 64","y":1938,"id":"1900-1940/304us64","sc":1,"op":3,"ar":1,"sum":"A case in which the Court overturned its prior decision in Swift v. Tyson and held that federal courts exercising diversity jurisdiction cannot create their own common law for issues that properly fall within state law.","sumSrc":"Oyez","by":{"0":"14, 17","2":"13","3":"21, 22"}},{"t":"case","label":"Felker v. Turpin","cite":"518 U.S. 651","y":1996,"id":"1995/95-8836","sc":1,"sum":"The unanimous Court held that the Act's creation of an appellate panel, charged with reviewing all second or successive habeas applications, is not unconstitutional. The Act simply transfers the duty of habeas review from the district courts to an appellate panel.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Graham v. Connor","cite":"490 U.S. 386","y":1989,"id":"1988/87-6571","sc":1,"sum":"In a unanimous ruling written by Justice William Rehnquist, the Court held that claims of excessive force used by government officials are properly analyzed under the Fourth Amendment’s “objective reasonableness” standard. The Court vacated the directed verdict and remanded the case to the district court to be decided by that standard.","sumSrc":"Oyez","by":{"0":"24","1":"13","2":"4"}},{"t":"case","label":"Gutierrez de Martinez v. Lamagno","cite":"515 U.S. 417","y":1995,"id":"1994/94-167","sc":1,"sum":"Invoking the federal court's jurisdiction based on diversity of citizenship, petitioners alleged in their complaint that they had suffered physical injuries and property damage as a result of an accident in Colombia caused by the negligence of respondent Lamagno, a federal employee. The United States Attorney, acting pursuant to the statute commonly known as the Westfall Act, 28 U. S. C. §2679(d)(1), certified on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","2":"30"}},{"t":"case","label":"Haig v. Agee","cite":"453 U.S. 280","y":1981,"id":"1980/80-83","sc":1,"op":1,"sum":"In a 7-to-2 decision, the Court held that Passport Act of 1926 and other congressional statutes implicitly granted the Secretary of State the power to revoke passports.","sumSrc":"Oyez","by":{"0":"29","2":"17"}},{"t":"case","label":"Harper v. Va. Dep’t of Taxation","cite":"509 U.S. 86","y":1993,"id":"1992/91-794","sc":1,"sum":"In Davis v. Michigan Dept. of Treasury,489 U. S. 803, this Court invalidated Michigan's practice of taxing retirement benefits paid by the Federal Government while exempting retirement benefits paid by the State or its political subdivisions. Because Michigan conceded that a refund to federal retirees was the appropriate remedy, the Court remanded for entry of judgment against the State. Virginia subsequently …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Hernandez v. Mesa","cite":"137 S. Ct. 291","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./137/291/","sc":1,"by":{"0":"6"}},{"t":"case","label":"Hernandez v. Mesa (“Hernández I”)","cite":"137 S. Ct. 2003","y":2017,"id":"2016/15-118","sc":1,"sum":"The Court determined that qualified immunity may not be granted based on facts that were unknown to the officer at the time of the incident, and that a court should consider whether an implied right of action is appropriate under Bivens v. Six Unknown Federal Narcotics Agents before addressing sensitive Fourth Amendment questions.","sumSrc":"Oyez","by":{"0":"passim","1":"10, 13, 26","2":"2, 3, 5, 6"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Hui v. Castaneda","cite":"559 U.S. 799","y":2010,"id":"2009/08-1529","sc":1,"op":1,"sum":"The Court held that the immunity granted by the Federal Tort Claims Act precludes Bivens actions against Public Health Service officers for constitutional violations committed while in the scope of the employees' official duties.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Kiobel v. Royal Dutch Petroleum Co.","cite":"569 U.S. 108","y":2012,"id":"2011/10-1491","sc":1,"op":4,"ar":2,"sum":"The Court found that the Alien Tort Statute does not give ground for United States law to be applied extraterrestrially to other sovereign nations with their own laws.","sumSrc":"Oyez","by":{"0":"32","1":"18, 19","2":"26, 27, 28","3":"10, 14"}},{"t":"case","label":"Kisela v. Hughes","cite":"138 S. Ct. 1148","y":2018,"id":"2017/17-467","sc":1,"sum":"The Court held that a police officer who shot a woman brandishing a knife but not otherwise engaging in threatening behavior was entitled to qualified immunity for his conduct.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Lanuza v. Love","cite":"899 F.3d 1019","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/899/1019/","op":3,"sum":"Recognizing a Bivens claim against a rogue immigration officer “does not threaten the political branches’ supervision of national security and foreign policy”.","sumSrc":"brief:0","by":{"0":"28"}},{"t":"case","label":"Larson v. Domestic & Foreign Commerce Corp.","cite":"337 U.S. 682","y":1949,"id":"scdb/1948-106","sc":1,"sum":"The suit was one against the United States 4nd, in the absence of consent by the United States, the District Court was without jurisdiction. Pp. 684-705. 2.' In determining whether a suit nominally against an officer is against the officer individually or against the sovereign, the crucial qukestion is whether the relief sought is relief against the sovereign. Pp. 687-688. Statement of the Case.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Manhattan Cmty. Access Corp. v. Halleck","cite":"139 S. Ct. 1921","y":2019,"id":"2018/17-1702","sc":1,"sum":"The Court held that Manhattan Community Access Corp, which operates public access channels, is not a state actor subject to constitutional liability.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"Meshal v. Higgenbotham","cite":"804 F.3d 417","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/804/417/","op":1,"ar":1,"by":{"0":"22","2":"24, 28","3":"10"}},{"t":"case","label":"Minneci v. Pollard","cite":"565 U.S. 118","y":2012,"id":"2011/10-1104","sc":1,"op":3,"sum":"The Court held that a prisoner cannot assert an Eighth Amendment claim for damages against private prison employees.","sumSrc":"Oyez","by":{"0":"1, 41","1":"8","2":"11","3":"1"}},{"t":"case","label":"Morrison v. Nat’l Austl. Bank","cite":"561 U.S. 247","y":2010,"id":"2009/08-1191","sc":1,"sum":"The Court held that the Securities and Exchange Act does not provide a cause of action against foreign plaintiffs suing foreign and American defendants for misconduct in connection with securities traded on foreign stock exchanges.","sumSrc":"Oyez","by":{"0":"31","1":"19, 20","2":"27","3":"13"}},{"t":"case","label":"Mullenix v. Luna","cite":"136 S. Ct. 305","y":2015,"id":"2015/14-1143","sc":1,"sum":"The Court determined that a trooper was entitled to qualified immunity for his actions in the context of the situation he faced.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Pearson v. Callahan","cite":"555 U.S. 223","y":2011,"id":"2008/07-751","sc":1,"sum":"A case in which the Court overturned its previous decision in Saucier v. Katz, which prescribed a rigid test for government qualified immunity claims, and held that inquiries should be at the discretion of the lower courts.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Poindexter v. Greenhow","cite":"114 U.S. 270","y":1885,"id":"scdb/1884-212","sc":1,"sum":"In an action of detinue for personal property,, distrained by the defendant for delinquent taxes, in payment of which the plaintiff had duly tendered coupons cut from bonds issued by the State of Virginia under the Funding Act of March 30;- -1871: Held,","sumSrc":"Headnote (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"RJR Nabisco, Inc. v. European Cmty.","cite":"136 S. Ct. 2090","y":2016,"id":"2015/15-138","sc":1,"op":2,"ar":2,"sum":"The Court held that some sections of the Racketeer Influenced Corrupt Organizations (RICO) statute can apply extraterritorially because Congress clearly based them on predicate offenses that can occur outside of the United States.","sumSrc":"Oyez","by":{"0":"31","2":"27, 28, 29","3":"13"}},{"t":"case","label":"Rodriguez v. Swartz","cite":"899 F.3d 719","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/899/719/","op":5,"by":{"0":"passim","1":"4, 20, 24, 27","2":"14","3":"6, 17"}},{"t":"case","label":"Sutton v. United States","cite":"819 F.2d 1289","y":1987,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/819/1289/","by":{"0":"22","3":"1"}},{"t":"case","label":"Tun-Cos v. Perrotte","cite":"922 F.3d 514","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/922/514/","by":{"0":"2"}},{"t":"case","label":"Turkmen v. Ashcroft","cite":"2018 WL 4026734","y":2018,"court":"E.D.N.Y. Aug. 13","by":{"0":"26"}},{"t":"case","label":"United States v. Smith","cite":"499 U.S. 160","y":1991,"id":"1990/89-1646","sc":1,"sum":"The Act immunizes Government employees from suit even when an FTCA exception precludes recovery against the Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Vanderklok v. United States","cite":"868 F.3d 189","y":2017,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/868/189/","by":{"0":"2","1":"17, 18","2":"21, 31"}},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1988,"id":"1987/86-1294","sc":1,"sum":"Section 102(c) of the National Security Act of 1947 (NSA) authorizes the Director of the Central Intelligence Agency (CIA), \"in his discretion,\" to terminate the employment of any CIA employee \"whenever he shall deem such termination necessary or advisable in the interests of the United States.\" After respondent, a covert electronics technician in the CIA's employ, voluntarily informed the agency that he was a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","2":"32","3":"19"}},{"t":"case","label":"Wheeldin v. Wheeler","cite":"373 U.S. 647","y":1963,"id":"1962/493","sc":1,"op":2,"sum":"Basing jurisdiction on 28 U. S. C. § 1331 and not alleging diversity of citizenship, petitioner Dawson brought suit in a Federal District Court against respondent, an investigator for the House Committee on Un-American Activities. Petitioner alleged that, without authorization from the Committee but acting under color of his office, respondent had caused a subpoena to appear as a witness before the Committee to be …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15","3":"22"}},{"t":"case","label":"Willingham v. Morgan","cite":"395 U.S. 402","y":1969,"id":"1968/228","sc":1,"sum":"Respondent, a federal prisoner, brought a tort action in state court against petitioners, the warden and chief medtval officer of a federal penitentiary, who then petitioned for removal of the action to the United States District Court under 28 U. S. C. § 1442 (a)(1). That statute allows removal to federal courts of any civil action against a federal officer \"for any act under colr of [his] office.\" Petitioners on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"137 S. Ct. 1843","y":2017,"id":"2016/15-1358","sc":1,"op":5,"sum":"The Court determined that, in suits against government officials for personally violating the Constitution, “context” should be defined narrowly for the purpose of determining whether a claim arose in a “new context,” and the government officials in this case are entitled to qualified immunity.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"passim","2":"passim"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"passim","2":"passim","3":"19"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3"}},{"t":"law","label":"Pub. L. No. 93-253","url":"https://www.govinfo.gov/link/statute/88/50","by":{"0":"34"}},{"t":"reg","label":"8 C.F.R. § 287.8","url":"https://www.ecfr.gov/current/title-8/section-287.8","subs":["(a)(2)(ii)"],"by":{"0":"22, 29","3":"5"}},{"t":"case","label":"Abdoulaye v. Cimaglia","cite":"2018 U.S. Dist. LEXIS 56167","y":2018,"court":"S.D.N.Y. Mar. 30","by":{"1":"23, 24"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"op":5,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"1":"7","3":"21"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"op":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"1":"7","2":"8","3":"1, 5"}},{"t":"case","label":"Bureau of Land Management, Wilkie v. Robbins","cite":"551 U.S. 537","y":2007,"id":"2006/06-219","sc":1,"op":3,"sum":"The Court ruled 7-2 that \"neither Bivens nor RICO gives Robbins a cause of action,\" so he could not sue the government for retaliation. In an opinion by Justice David Souter, the Court declined to extend the availability of Bivens actions to cases of retaliation for the exercise of the right to exclude the government from one's property.","sumSrc":"Oyez","by":{"1":"27, 8, 21","2":"10, 11, 22, 29, 30, 33","3":"1"}},{"t":"case","label":"Burwell v. Hobby Lobby Stores, Inc.","cite":"573 U.S. 682","y":2014,"id":"2013/13-354","sc":1,"sum":"The Court decided that the Affordable Care Act's requirement of for-profit corporations to supply its employees with contraceptives that go against the owners' beliefs is unconstitutional under the Religious Freedom Restoration Act of 1993.","sumSrc":"Oyez","by":{"1":"28, 29"}},{"t":"case","label":"Bush v. Lucas","cite":"462 U.S. 367","y":1983,"id":"1982/81-469","sc":1,"op":3,"sum":"Not under the CSC regulations. The federal judiciary, pursuant to its common law authority, has the power to recognize new causes of action in absence of, or to supplement, statutory remedies unless Congress has expressly indicated its relief is to be exclusive.","sumSrc":"Oyez","by":{"1":"7, 21","2":"11, 20, 22, 26","3":"1"}},{"t":"case","label":"Cannon v. Univ. of Chi.","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"7"}},{"t":"case","label":"Chappell v. Wallace","cite":"462 U.S. 296","y":1983,"id":"1982/82-167","sc":1,"op":4,"ar":2,"sum":"Enlisted military personnel may not maintain a suit to recover damages from a superior officer for alleged constitutional violations. The special status of the military has required, the Constitution has contemplated, Congress has created, and this Court has long recognized two systems of justice: one for civilians and one for military personnel. The need for unhesitating and decisive action by military officers and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"7, 12","2":"11","3":"1"}},{"t":"case","label":"Cuevas v. United States","cite":"2018 U.S. Dist. LEXIS 44915","y":2018,"court":"D. Colo. Mar. 19","by":{"1":"22"}},{"t":"case","label":"Doe v. Rumsfeld","cite":"683 F.3d 390","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/683/390/","by":{"1":"16"}},{"t":"case","label":"EEOC v. Arabian American Oil Co.","cite":"499 U.S. 244","y":1991,"id":"1990/89-1838","sc":1,"op":1,"sum":"Title VII does not apply extraterritorially to regulate the employment practices of United States firms that employ American citizens abroad. Petitioners' evidence, while not totally lacking in probative value, falls short of demonstrating the clearly expressed affirmative congressional intent that is required to overcome the well-established presumption against statutory extraterritoriality.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"op":2,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"8","2":"11","3":"1"}},{"t":"case","label":"Free v. Peikar","cite":"2018 U.S. Dist. LEXIS 25293","y":2018,"court":"E.D. Cal. Feb. 15","by":{"1":"23"}},{"t":"case","label":"Hernandez v. Mesa","cite":"885 F.3d 811","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/885/811/","op":6,"by":{"1":"passim"}},{"t":"case","label":"Hernandez v. Mesa","cite":"785 F.3d 117","y":2015,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/785/117/","op":3,"by":{"1":"1"}},{"t":"case","label":"Hernandez v. United States","cite":"757 F.3d 249","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/757/249/","by":{"1":"27, 28"}},{"t":"case","label":"J.I. Case Co. v. Borak","cite":"377 U.S. 426","y":1964,"id":"1963/402","sc":1,"op":4,"ar":1,"sum":"Respondent, stockholder of petitioner company, brought a civil action in federal court for deprivation of his and other stockholders' preemptive rights by reason of a merger involving the company, allegedly effected through use of a false and misleading proxy statement. The complaint has two counts, one based on diversity and claiming a breach of directors' fiduciary duty to stockholders and the other alleging a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"6","2":"12"}},{"t":"case","label":"Leibelson v. Collins","cite":"2017 U.S. Dist. LEXIS 212026","y":2017,"court":"S.D. W. Va. Dec. 27","by":{"1":"22"}},{"t":"case","label":"Linlor v. Polson","cite":"263 F. Supp. 3d 613","y":2017,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/263/613/","by":{"1":"22, 23"}},{"t":"case","label":"Morgan v. Shivers","cite":"2018 U.S. Dist. LEXIS 14235","y":2018,"court":"S.D.N.Y. Jan. 29","by":{"1":"23"}},{"t":"case","label":"Nw. Austin Mun. Util. Dist. No. One v. Holder","cite":"557 U.S. 193","y":2009,"id":"2008/08-322","sc":1,"sum":"The Court held that the Voting Rights Act (VRA) permits all political subdivisions to seek bailout from the preclearance requirements of the VRA.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Schweiker v. Chilicky","cite":"487 U.S. 412","y":1988,"id":"1987/86-1781","sc":1,"op":3,"sum":"The Court held that when a government employee violates a citizen’s legal rights, that citizen is not allowed to pursue monetary damages as compensation when the violated statute does not contain monetary damages as a possible remedy.","sumSrc":"Oyez","by":{"1":"8, 20","2":"passim","3":"1"}},{"t":"case","label":"Shelby Cty. v. Holder","cite":"570 U.S. 529","y":2013,"id":"2012/12-96","sc":1,"sum":"The Court found that Section 4 of the Voting Rights Act was unconstitutional.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Turkmen v. Ashcroft","cite":"2018 U.S. Dist. LEXIS 137492","y":2018,"court":"E.D.N.Y.","by":{"1":"21"}},{"t":"case","label":"United States v. Delgado–Garcia","cite":"374 F.3d 1337","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/374/1337/","by":{"1":"16","2":"21"}},{"t":"case","label":"United States v. Stanley","cite":"483 U.S. 669","y":1987,"id":"1986/86-393","sc":1,"op":4,"sum":"The Supreme Court held that the Court of Appeals did not have the jurisdiction to consider Stanley’s FTCA claims because they were not a part of the order that was originally appealed. The Court also held that the Court of Appeals took an unnecessarily narrow view of the Chappell decision by limiting it to an even greater extent than the FTCA waiver of governmental liability.","sumSrc":"Oyez","by":{"1":"7","2":"passim","3":"1"}},{"t":"case","label":"United States v. Verdugo–Urquidez","cite":"494 U.S. 259","y":1990,"id":"1989/88-1353","sc":1,"op":4,"ar":4,"sum":"The text of the Fourth Amendment concerns \"the people,\" suggesting a concern with persons who are part of the national community, as contrasted with aliens without any substantial connection to the U.S. Moreover, extraterritorial aliens are not even entitled to rights under the Fifth Amendment, which speaks in the relatively more universal term of \"person.\" And non-\"fundamental\" rights are not even guaranteed to inhabitants of unincorporated territories under U.S sovereign control, much less aliens.","sumSrc":"Oyez","by":{"1":"13, 26","2":"4"}},{"t":"case","label":"Vega v. United States","cite":"881 F.3d 1146","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/881/1146/","by":{"1":"21"}},{"t":"const","label":"Article I, Section 9, Clause 2","clauses":[["habeas","Suspension Clause (Habeas Corpus)"]],"text":"The Privilege of the Writ of Habeas Corpus shall not be suspended, unless when in Cases of Rebellion or Invasion the public Safety may require it.","by":{"1":"14"}},{"t":"usc","label":"6 U.S.C. § 211","url":"https://www.law.cornell.edu/uscode/text/6/211","subs":["(c)","(e)(3)(B)"],"stext":{"head":"§211. Establishment of U.S. Customs and Border Protection; Commissioner, Deputy Commissioner, and operational offices","paras":[[0,"(a) In general"],[0,"There is established in the Department an agency to be known as U.S. Customs and Border Protection."],[0,"(b) Commissioner of U.S. Customs and Border Protection"],[0,"(1) In general"],[1,"There shall be at the head of U.S. Customs and Border Protection a Commissioner of U.S. Customs and Border Protection (in this section referred to as the \"Commissioner\")."],[0,"(2) Committee referral"],[1,"As an exercise of the rulemaking power of the Senate, any nomination for the Commissioner submitted to the Senate for confirmation, and referred to a committee, shall be referred to the Committee on Finance."],[0,"(c) Duties"],[0,"The Commissioner shall—"],[1,"(1) coordinate and integrate the security, trade facilitation, and trade enforcement functions of U.S. Customs and Border Protection;"],[1,"(2) ensure the interdiction of persons and goods illegally entering or exiting the United States;"],[1,"(3) facilitate and expedite the flow of legitimate travelers and trade;"],[1,"(4) direct and administer the commercial operations of U.S. Customs and Border Protection, and the enforcement of the customs and trade laws of the United States;"],[1,"(5) detect, respond to, and interdict terrorists, drug smugglers and traffickers, human smugglers and traffickers, and other persons who may undermine the security of the United States, in cases in which such persons are entering, or have recently entered, the United States;"],[1,"(6) safeguard the borders of the United States to protect against the entry of dangerous goods;"],[1,"(7) ensure the overall economic security of the United States is not diminished by efforts, activities, and programs aimed at securing the homeland;"],[1,"(8) in coordination with U.S. Immigration and Customs Enforcement and United States Citizenship and Immigration Services, enforce and administer all immigration laws, as such term is defined in paragraph (17) of section 1101(a) of title 8, including—"],[2,"(A) the inspection, processing, and admission of persons who seek to enter or depart the United States; and"],[2,"(B) the detection, interdiction, removal, departure from the United States, short-term detention, and transfer of persons unlawfully entering, or who have recently unlawfully entered, the United States;"],[1,"(9) develop and implement screening and targeting capabilities, including the screening, reviewing, identifying, and prioritizing of passengers and cargo across all international modes of transportation, both inbound and outbound;"],[1,"(10) in coordination with the Secretary, deploy technology to collect the data necessary for the Secretary to administer the biometric entry and exit data system pursuant to section 1365b of title 8;"],[1,"(11) enforce and administer the laws relating to agricultural import and entry inspection referred to in section 231 of this title;"],[1,"(12) in coordination with the Under Secretary for Management of the Department, ensure U.S. Customs and Border Protection complies with Federal law, the Federal Acquisition Regulation, and the Department's acquisition management directives for major acquisition programs of U.S. Customs and Border Protection;"],[1,"(13) ensure that the policies and regulations of U.S. Customs and Border Protection are consistent with the obligations of the United States pursuant to international agreements;"],[1,"(14) enforce and administer—"],[2,"(A) the Container Security Initiative program under section 205 of the Security and Accountability for Every Port Act of 2006 (6 U.S.C. 945); and"],[2,"(B) the Customs–Trade Partnership Against Terrorism program under subtitle B of title II of such Act (6 U.S.C. 961 et seq.);"],[1,"(15) conduct polygraph examinations in accordance with section 221(1) of this title;"],[1,"(16) establish the standard operating procedures described in subsection (k);"],[1,"(17) carry out the training required under subsection (l);"],[1,"(18) carry out section 218 of this title, relating to the issuance of Asia-Pacific Economic Cooperation Business Travel Cards; and"],[1,"(19) carry out other duties and powers prescribed by law or delegated by the Secretary."],[0,"(d) Deputy Commissioner"],[0,"There shall be in U.S. Customs and Border Protection a Deputy Commissioner who shall assist the Commissioner in the management of U.S. Customs and Border Protection."],[0,"(e) U.S. Border Patrol"],[0,"(1) In general"],[1,"There is established in U.S. Customs and Border Protection the U.S. Border Patrol."],[0,"(2) Chief"],[1,"There shall be at the head of the U.S. Border Patrol a Chief, who shall—"],[2,"(A) be at the level of Executive Assistant Commissioner within U.S. Customs and Border Protection; and"],[2,"(B) report to the Commissioner."],[0,"(3) Duties"],[1,"The U.S. Border Patrol shall—"],[2,"(A) serve as the law enforcement office of U.S. Customs and Border Protection with primary responsibility for interdicting persons attempting to illegally enter or exit the United States or goods being illegally imported into or exported from the United States at a place other than a designated port of entry;"],[2,"(B) deter and prevent the illegal entry of terrorists, terrorist weapons, persons, and contraband; and"],[2,"(C) carry out other duties and powers prescribed by the Commissioner."],[0,"(f) Air and Marine Operations"],[0,"(1) In general"],[1,"There is established in U.S. Customs and Border Protection an office known as Air and Marine Operations."],[0,"(2) Executive Assistant Commissioner"],[1,"There shall be at the head of Air and Marine Operations an Executive Assistant Commissioner, who shall report to the Commissioner."],[0,"(3) Duties"],[1,"Air and Marine Operations shall—"],[2,"(A) serve as the law enforcement office within U.S. Customs and Border Protection with primary responsibility to detect, interdict, and prevent acts of terrorism and the unlawful movement of people, illicit drugs, and other contraband across the borders of the United States in the air and maritime environment;"],[2,"(B) conduct joint aviation and marine operations with U.S. Immigration and Customs Enforcement;"],[2,"(C) conduct aviation and marine operations with international, Federal, State, and local law enforcement agencies, as appropriate;"],[2,"(D) administer the Air and Marine Operations Center established under paragraph (4); and"],[2,"(E) carry out other duties and powers prescribed by the Commissioner."],[0,"(4) Air and Marine Operations Center"],[0,"(A) In general"],[2,"There is established in Air and Marine Operations an Air and Marine Operations Center."],[0,"(B) Executive Director"],[2,"There shall be at the head of the Air and Marine Operations Center an Executive Director, who shall report to the Executive Assistant Commissioner of Air and Marine Operations."],[0,"(C) Duties"],[2,"The Air and Marine Operations Center shall—"],[3,"(i) manage the air and maritime domain awareness of the Department, as directed by the Secretary;"],[3,"(ii) monitor and coordinate the airspace for unmanned aerial systems operations of Air and Marine Operations in U.S. Customs and Border Protection;"],[3,"(iii) detect, identify, and coordinate a response to threats to national security in the air domain, in coordination with other appropriate agencies, as determined by the Executive Assistant Commissioner;"],[3,"(iv) provide aviation and marine support to other Federal, State, tribal, and local agencies; and"],[3,"(v) carry out other duties and powers prescribed by the Executive Assistant Commissioner."],[0,"(g) Office of Field Operations"],[0,"(1) In general"],[1,"There is established in U.S. Customs and Border Protection an Office of Field Operations."],[0,"(2) Executive Assistant Commissioner"],[1,"There shall be at the head of the Office of Field Operations an Executive Assistant Commissioner, who shall report to the Commissioner."],[0,"(3) Duties"],[1,"The Office of Field Operations shall coordinate the enforcement activities of U.S. Customs and Border Protection at United States air, land, and sea ports of entry to—"],[2,"(A) deter and prevent terrorists and terrorist weapons from entering the United States at such ports of entry;"],[2,"(B) conduct inspections at such ports of entry to safeguard the United States from terrorism and illegal entry of persons;"],[2,"(C) prevent illicit drugs, agricultural pests, and contraband from entering the United States;"],[2,"(D) in coordination with the Commissioner, facilitate and expedite the flow of legitimate travelers and trade;"],[2,"(E) administer the National Targeting Center established under paragraph (4);"],[2,"(F) coordinate with the Executive Assistant Commissioner for the Office of Trade with respect to the trade facilitation and trade enforcement activities of U.S. Customs and Border Protection; and"],[2,"(G) carry out other duties and powers prescribed by the Commissioner."],[0,"(4) National Targeting Center"],[0,"(A) In general"],[2,"There is established in the Office of Field Operations a National Targeting Center."],[0,"(B) Executive Director"],[2,"There shall be at the head of the National Targeting Center an Executive Director, who shall report to the Executive Assistant Commissioner of the Office of Field Operations."],[0,"(C) Duties"],[2,"The National Targeting Center shall—"],[3,"(i) serve as the primary forum for targeting operations within U.S. Customs and Border Protection to collect and analyze traveler and cargo information in advance of arrival in the United States to identify and address security risks and strengthen trade enforcement;"],[3,"(ii) identify, review, and target travelers and cargo for examination;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/6/211?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§211. Establishment of U.S. Customs and Border Protection; Commissioner, Deputy Commissioner, and operational offices","tname":"Domestic Security","by":{"1":"17, 26","2":"21, 21"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":11,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"1":"11","2":"9, 22, 23, 26","3":"9"}},{"t":"case","label":"Bank Markazi v. Peterson","cite":"136 S. Ct. 1310","y":2016,"id":"2015/14-770","sc":1,"sum":"The Court decided that a statute effectively directing a particular result in a single pending case does not violate the separation of powers.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Blue Chip Stamps v. Manor Drug Stores","cite":"421 U.S. 723","y":1975,"id":"1974/74-124","sc":1,"op":1,"sum":"A private damages action under Rule 10b-5 is confined to actual purchasers or sellers of securities and the Birnbaum rule bars respondent from maintaining this suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"City of Milwaukee v. Illinois","cite":"451 U.S. 304","y":1981,"id":"1980/79-408","sc":1,"sum":"In original proceedings brought by respondent State of Illinois, alleging that petitioners-the city of Milwaukee, its Sewerage Commission, and Milwaukee County's Metropolitan Sewerage Commission-and other Wisconsin cities were polluting Lake Michigan because of overflows of untreated sewage from their sewer systems and discharges of inadequately treated sewage from their treatment plants, this Court recognized the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"Department of Navy v. Egan","cite":"484 U.S. 518","y":1988,"id":"1987/86-1552","sc":1,"op":1,"sum":"In an appeal pursuant to § 7513, the Board does not have authority to review the substance of an underlying security-clearance determination in the course of reviewing an adverse action.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Hartman v. Moore","cite":"547 U.S. 250","y":2006,"id":"2005/04-1495","sc":1,"op":1,"sum":"The Court ruled in favor of the postal inspectors, overruling the Court of Appeals. The opinion by Justice David Souter held that plaintiffs alleging retaliatory prosecution must prove that the law enforcement agents lacked probable cause. Probable cause, the Court ruled, is a crucial component of the \"chain of causation\" needed to evaluate retaliatory prosecution charges.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Imbler v. Pachtman","cite":"424 U.S. 409","y":1976,"id":"1975/74-5435","sc":1,"sum":"The Court held that prosecutors have the same absolute immunity under Section 1983 that they had under common law in malicious prosecution suits.","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"Jamison v. Wiley","cite":"14 F.3d 222","y":1994,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/14/222/","by":{"2":"31"}},{"t":"case","label":"Oetjen v. Central Leather Co.","cite":"246 U.S. 297","y":1918,"id":"scdb/1917-085","sc":1,"sum":"The court notices judicially that the Government of the United States recognized the Government of Carranza as the de facto government of the Republic of Mexico, on October 19, 1915, and as the fie jure government on August 31, 1917.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"17"}},{"t":"case","label":"Sanchez-Espinoza v. Reagan","cite":"770 F.2d 202","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/770/202/","op":1,"by":{"2":"18","3":"4"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"op":3,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"2":"23","3":"11"}},{"t":"case","label":"United States v. Cienfuegos","cite":"462 F.3d 1160","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/462/1160/","by":{"2":"31"}},{"t":"const","label":"Article II, Section 2","clauses":[["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"]],"text":"The President shall be Commander in Chief of the Army and Navy of the United States, and of the Militia of the several States, when called into the actual Service of the United States; he may require the Opinion, in writing, of the principal Officer in each of the executive Departments, upon any Subject relating to the Duties of their respective Offices, and he shall have Power to grant Reprieves and Pardons for Offences against the United States, except in Cases of Impeachment. He shall have Power, by and with the Advice and Consent of the Senate, to make Treaties, provided two thirds of the Senators present concur; and he shall nominate, and by and with the Advice and Consent of the Senate, shall appoint Ambassadors, other public Ministers and Consuls, Judges of the supreme Court, and all other Officers of the United States, whose Appointments are not herein otherwise provided for, and which shall be established by Law: but the Congress may by Law vest the Appointment of such inferior Officers, as they think proper, in the President alone, in the Courts of Law, or in the Heads of Departments. The President shall have Power to fill up all Vacancies that may happen during the Recess of the Senate, by granting Commissions which shall expire at the End of their next Session.","by":{"2":"17"}},{"t":"const","label":"Amendment VIII","clauses":[["eighth-amendment","Eighth Amendment"]],"text":"Excessive bail shall not be required, nor excessive fines imposed, nor cruel and unusual punishments inflicted.","by":{"2":"11"}},{"t":"usc","label":"28 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/28/1350","stext":{"head":"§1350. Alien's action for tort","paras":[[0,"The district courts shall have original jurisdiction of any civil action by an alien for a tort only, committed in violation of the law of nations or a treaty of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1350?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1350. Alien's action for tort","tname":"Judiciary and Judicial Procedure","by":{"2":"3, 24"}},{"t":"usc","label":"28 U.S.C. § 2671","url":"https://www.law.cornell.edu/uscode/text/28/2671","by":{"2":"3"}},{"t":"usc","label":"28 U.S.C. § 2674","url":"https://www.law.cornell.edu/uscode/text/28/2674","by":{"2":"23"}},{"t":"usc","label":"28 U.S.C. § 2680","url":"https://www.law.cornell.edu/uscode/text/28/2680","subs":["(k)"],"stext":{"head":"§2680. Exceptions","paras":[[0,"The provisions of this chapter and section 1346(b) of this title shall not apply to—"],[0,"(a) Any claim based upon an act or omission of an employee of the Government, exercising due care, in the execution of a statute or regulation, whether or not such statute or regulation be valid, or based upon the exercise or performance or the failure to exercise or perform a discretionary function or duty on the part of a federal agency or an employee of the Government, whether or not the discretion involved be abused."],[0,"(b) Any claim arising out of the loss, miscarriage, or negligent transmission of letters or postal matter."],[0,"(c) Any claim arising in respect of the assessment or collection of any tax or customs duty, or the detention of any goods, merchandise, or other property by any officer of customs or excise or any other law enforcement officer, except that the provisions of this chapter and section 1346(b) of this title apply to any claim based on injury or loss of goods, merchandise, or other property, while in the possession of any officer of customs or excise or any other law enforcement officer, if—"],[1,"(1) the property was seized for the purpose of forfeiture under any provision of Federal law providing for the forfeiture of property other than as a sentence imposed upon conviction of a criminal offense;"],[1,"(2) the interest of the claimant was not forfeited;"],[1,"(3) the interest of the claimant was not remitted or mitigated (if the property was subject to forfeiture); and"],[1,"(4) the claimant was not convicted of a crime for which the interest of the claimant in the property was subject to forfeiture under a Federal criminal forfeiture law..1"],[0,"(d) Any claim for which a remedy is provided by chapter 309 or 311 of title 46 relating to claims or suits in admiralty against the United States."],[0,"(e) Any claim arising out of an act or omission of any employee of the Government in administering the provisions of sections 1–31 of Title 50, Appendix.2"],[0,"(f) Any claim for damages caused by the imposition or establishment of a quarantine by the United States."],[0,"[(g) Repealed. Sept. 26, 1950, ch. 1049, §13 (5), 64 Stat. 1043.]"],[0,"(h) Any claim arising out of assault, battery, false imprisonment, false arrest, malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights: Provided, That, with regard to acts or omissions of investigative or law enforcement officers of the United States Government, the provisions of this chapter and section 1346(b) of this title shall apply to any claim arising, on or after the date of the enactment of this proviso, out of assault, battery, false imprisonment, false arrest, abuse of process, or malicious prosecution. For the purpose of this subsection, \"investigative or law enforcement officer\" means any officer of the United States who is empowered by law to execute searches, to seize evidence, or to make arrests for violations of Federal law."],[0,"(i) Any claim for damages caused by the fiscal operations of the Treasury or by the regulation of the monetary system."],[0,"(j) Any claim arising out of the combatant activities of the military or naval forces, or the Coast Guard, during time of war."],[0,"(k) Any claim arising in a foreign country."],[0,"(l) Any claim arising from the activities of the Tennessee Valley Authority."],[0,"(m) Any claim arising from the activities of the Panama Canal Company."],[0,"(n) Any claim arising from the activities of a Federal land bank, a Federal intermediate credit bank, or a bank for cooperatives."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2680?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2680. Exceptions","tname":"Judiciary and Judicial Procedure","by":{"2":"23, 34"}},{"t":"usc","label":"10 U.S.C. § 2734","url":"https://www.law.cornell.edu/uscode/text/10/2734","subs":["(a)","(a)(3)","(b)"],"stext":{"head":"§2734. Property loss; personal injury or death: incident to noncombat activities of the armed forces; foreign countries","paras":[[0,"(a) To promote and to maintain friendly relations through the prompt settlement of meritorious claims, the Secretary concerned, or an officer or employee designated by the Secretary, may appoint, under such regulations as the Secretary may prescribe, one or more claims commissions, each composed of one or more officers or employees or combination of officers or employees of the armed forces, to settle and pay in an amount not more than $100,000, a claim against the United States for—"],[1,"(1) damage to, or loss of, real property of any foreign country or of any political subdivision or inhabitant of a foreign country, including damage or loss incident to use and occupancy;"],[1,"(2) damage to, or loss of, personal property of any foreign country or of any political subdivision or inhabitant of a foreign country, including property bailed to the United States; or"],[1,"(3) personal injury to, or death of, any inhabitant of a foreign country;"],[0,"if the damage, loss, personal injury, or death occurs outside the United States, or the Commonwealths or possessions, and is caused by, or is otherwise incident to noncombat activities of, the armed forces under his jurisdiction, or is caused by a member thereof or by a civilian employee of the military department concerned or the Coast Guard, as the case may be. The claim of an insured, but not that of a subrogee, may be considered under this subsection. In this section, \"foreign country\" includes any place under the jurisdiction of the United States in a foreign country. An officer or employee may serve on a claims commission under the jurisdiction of another armed force only with the consent of the Secretary of his department, or his designee, but shall perform his duties under regulations of the department appointing the commission."],[0,"(b) A claim may be allowed under subsection (a) only if—"],[1,"(1) it is presented within two years after it accrues;"],[1,"(2) in the case of a national of a country at war with the United States, or of any ally of that country, the claimant is determined by the commission or by the local military commander to be friendly to the United States; and"],[1,"(3) it did not arise from action by an enemy or result directly or indirectly from an act of the armed forces of the United States in combat, except that a claim may be allowed if it arises from an accident or malfunction incident to the operation of an aircraft of the armed forces of the United States, including its airborne ordnance, indirectly related to combat, and occurring while preparing for, going to, or returning from a combat mission."],[0,"(c) The Secretary concerned may appoint any officer or employee under the jurisdiction of the Secretary to act as an approval authority for claims determined to be allowable under subsection (a) in an amount in excess of $10,000."],[0,"(d) If the Secretary concerned considers that a claim in excess of $100,000 is meritorious, and the claim otherwise is payable under this section, the Secretary may pay the claimant $100,000 and report any meritorious amount in excess of $100,000 to the Secretary of the Treasury for payment under section 1304 of title 31."],[0,"(e) Except as provided in subsection (d), no claim may be paid under this section unless the amount tendered is accepted by the claimant in full satisfaction."],[0,"(f) Upon the request of the department concerned, a claim arising in that department and covered by subsection (a) may be settled and paid by a commission appointed under subsection (a) and composed of officers of an armed force under the jurisdiction of another department."],[0,"(g) Payment of claims against the Coast Guard arising while it is operating as a service in the Department of Homeland Security shall be made out of the appropriation for the operating expenses of the Coast Guard."],[0,"(h) The Secretary of Defense may designate any claims commission appointed under subsection (a) to settle and pay, as provided in this section, claims for damage caused by a civilian employee of the Department of Defense other than an employee of a military department. Payments of claims under this subsection shall be made from appropriations as provided in section 2732 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/2734?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2734. Property loss; personal injury or death: incident to noncombat activities of the armed forces; foreign countries","tname":"Armed Forces","by":{"2":"25, 25, 25","3":"16"}},{"t":"usc","label":"10 U.S.C. § 2734a","url":"https://www.law.cornell.edu/uscode/text/10/2734a","subs":["(a)"],"stext":{"head":"§2734a. Property loss; personal injury or death: incident to noncombat activities of armed forces in foreign countries; international agreements","paras":[[0,"(a) When the United States is a party to an international agreement which provides for the settlement or adjudication and cost sharing of claims against the United States arising out of the acts or omissions of a member or civilian employee of an armed force of the United States done in the performance of official duty, or arising out of any other act, omission, or occurrence for which an armed force of the United States is legally responsible under the law of another party to the international agreement, and causing damage in the territory of such party, the Secretary of Defense or the Secretary of Homeland Security or their designees may—"],[1,"(1) reimburse the party to the agreement for the agreed pro rata share of amounts, including any authorized arbitration costs, paid by that party in satisfying awards or judgments on claims, in accordance with the agreement; or"],[1,"(2) pay the party to the agreement the agreed pro rata share of any claim, including any authorized arbitration costs, for damage to property owned by it, in accordance with the agreement."],[0,"(b) A claim arising out of an act of an enemy of the United States or arising, directly or indirectly, from an act of the armed forces, or a member thereof, while engaged in combat may not be considered or paid under this section."],[0,"(c) A reimbursement or payment under this section shall be made by the Secretary of Defense out of appropriations as provided in section 2732 of this title except that payment of claims against the Coast Guard arising while it is operating as a service of the Department of Homeland Security shall be made out of the appropriations for the operating expenses of the Coast Guard. The appropriations referred to in this subsection may be used to buy foreign currencies required for the reimbursement or payment."],[0,"(d) Upon the request of the Secretary of Homeland Security or his designee, any payments made relating to claims arising from the activities of the Coast Guard and covered by subsection (a) may be reimbursed or paid to the foreign country concerned by the authorized representative of the Department of Defense out of appropriations as provided in section 2732 of this title, subject to reimbursement from the Department of Homeland Security."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/2734a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2734a. Property loss; personal injury or death: incident to noncombat activities of armed forces in foreign countries; international agreements","tname":"Armed Forces","by":{"2":"25, 25"}},{"t":"law","label":"Pub. L. No. 102-256","url":"https://www.govinfo.gov/link/statute/106/73","by":{"2":"24"}},{"t":"usc","label":"28 U.S.C. § 2679","url":"https://www.law.cornell.edu/uscode/text/28/2679","subs":["(b)","(b)(2)(A)","(d)"],"stext":{"head":"§2679. Exclusiveness of remedy","paras":[[0,"(a) The authority of any federal agency to sue and be sued in its own name shall not be construed to authorize suits against such federal agency on claims which are cognizable under section 1346(b) of this title, and the remedies provided by this title in such cases shall be exclusive."],[0,"(b)(1) The remedy against the United States provided by sections 1346(b) and 2672 of this title for injury or loss of property, or personal injury or death arising or resulting from the negligent or wrongful act or omission of any employee of the Government while acting within the scope of his office or employment is exclusive of any other civil action or proceeding for money damages by reason of the same subject matter against the employee whose act or omission gave rise to the claim or against the estate of such employee. Any other civil action or proceeding for money damages arising out of or relating to the same subject matter against the employee or the employee's estate is precluded without regard to when the act or omission occurred."],[0,"(2) Paragraph (1) does not extend or apply to a civil action against an employee of the Government—"],[1,"(A) which is brought for a violation of the Constitution of the United States, or"],[1,"(B) which is brought for a violation of a statute of the United States under which such action against an individual is otherwise authorized."],[0,"(c) The Attorney General shall defend any civil action or proceeding brought in any court against any employee of the Government or his estate for any such damage or injury. The employee against whom such civil action or proceeding is brought shall deliver within such time after date of service or knowledge of service as determined by the Attorney General, all process served upon him or an attested true copy thereof to his immediate superior or to whomever was designated by the head of his department to receive such papers and such person shall promptly furnish copies of the pleadings and process therein to the United States attorney for the district embracing the place wherein the proceeding is brought, to the Attorney General, and to the head of his employing Federal agency."],[0,"(d)(1) Upon certification by the Attorney General that the defendant employee was acting within the scope of his office or employment at the time of the incident out of which the claim arose, any civil action or proceeding commenced upon such claim in a United States district court shall be deemed an action against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant."],[0,"(2) Upon certification by the Attorney General that the defendant employee was acting within the scope of his office or employment at the time of the incident out of which the claim arose, any civil action or proceeding commenced upon such claim in a State court shall be removed without bond at any time before trial by the Attorney General to the district court of the United States for the district and division embracing the place in which the action or proceeding is pending. Such action or proceeding shall be deemed to be an action or proceeding brought against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant. This certification of the Attorney General shall conclusively establish scope of office or employment for purposes of removal."],[0,"(3) In the event that the Attorney General has refused to certify scope of office or employment under this section, the employee may at any time before trial petition the court to find and certify that the employee was acting within the scope of his office or employment. Upon such certification by the court, such action or proceeding shall be deemed to be an action or proceeding brought against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant. A copy of the petition shall be served upon the United States in accordance with the provisions of Rule 4(d)(4) 1 of the Federal Rules of Civil Procedure. In the event the petition is filed in a civil action or proceeding pending in a State court, the action or proceeding may be removed without bond by the Attorney General to the district court of the United States for the district and division embracing the place in which it is pending. If, in considering the petition, the district court determines that the employee was not acting within the scope of his office or employment, the action or proceeding shall be remanded to the State court."],[0,"(4) Upon certification, any action or proceeding subject to paragraph (1), (2), or (3) shall proceed in the same manner as any action against the United States filed pursuant to section 1346(b) of this title and shall be subject to the limitations and exceptions applicable to those actions."],[0,"(5) Whenever an action or proceeding in which the United States is substituted as the party defendant under this subsection is dismissed for failure first to present a claim pursuant to section 2675(a) of this title, such a claim shall be deemed to be timely presented under section 2401(b) of this title if—"],[1,"(A) the claim would have been timely had it been filed on the date the underlying civil action was commenced, and"],[1,"(B) the claim is presented to the appropriate Federal agency within 60 days after dismissal of the civil action."],[0,"(e) The Attorney General may compromise or settle any claim asserted in such civil action or proceeding in the manner provided in section 2677, and with the same effect."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2679?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§2679. Exclusiveness of remedy","tname":"Judiciary and Judicial Procedure","by":{"2":"4, 30, 32, 33, 30"}},{"t":"usc","label":"6 U.S.C. § 111","url":"https://www.law.cornell.edu/uscode/text/6/111","subs":["(b)(1)(A)","(b)(1)(E)"],"by":{"2":"21, 21"}},{"t":"usc","label":"8 U.S.C. § 1357","url":"https://www.law.cornell.edu/uscode/text/8/1357","subs":["(a)(5)"],"by":{"2":"31"}},{"t":"usc","label":"18 U.S.C. § 3663A","url":"https://www.law.cornell.edu/uscode/text/18/3663A","subs":["(a)"],"by":{"2":"31"}},{"t":"usc","label":"21 U.S.C. § 904","url":"https://www.law.cornell.edu/uscode/text/21/904","stext":{"head":"§904. Payment of tort claims","paras":[[0,"Notwithstanding section 2680(k) of title 28, the Attorney General, in carrying out the functions of the Department of Justice under this subchapter, is authorized to pay tort claims in the manner authorized by section 2672 of title 28, when such claims arise in a foreign country in connection with the operations of the Drug Enforcement Administration abroad."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/904?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§904. Payment of tort claims","tname":"Food and Drugs","by":{"2":"25"}},{"t":"usc","label":"22 U.S.C. § 2669","url":"https://www.law.cornell.edu/uscode/text/22/2669","subs":["(b)"],"stext":{"head":"§2669. Printing and binding outside continental United States; settlement and payment of claims by foreign governments; employment of aliens; official functions and courtesies; purchase of uniforms; payment of tort claims; payment of assumed obligations in Germany; telecommunications services; security; special purpose passenger motor vehicles; pay obligations arising under international conventions or contracts; personal service contracts","paras":[[0,"The Secretary of State may use funds appropriated or otherwise available to the Secretary to—"],[1,"(a) provide for printing and binding outside the States of the United States and the District of Columbia without regard to section 501 of title 44;"],[1,"(b) for the purpose of promoting and maintaining friendly relations with foreign countries through the prompt settlement of certain claims, settle and pay any meritorious claim against the United States which is presented by a government of a foreign country for damage to or loss of real or personal property of, or personal injury to or death of, any national of such foreign country: Provided, That such claim is not cognizable under any other statute or international agreement of the United States and can be settled for not more than $15,000 or the foreign currency equivalent thereof;"],[1,"(c) employ individuals or organizations, by contract, for services abroad, and individuals employed by contract to perform such services shall not by virtue of such employment be considered to be employees of the United States Government for purposes of any law administered by the Office of Personnel Management (except that the Secretary may determine the applicability to such individuals of subsection (f) and of any other law administered by the Secretary concerning the employment of such individuals abroad); and such contracts are authorized to be negotiated, the terms of the contracts to be prescribed, and the work to be performed, where necessary, without regard to such statutory provisions as relate to the negotiation, making, and performance of contracts and performance of work in the United States;"],[1,"(d) provide for official functions and courtesies;"],[1,"(e) purchase uniforms;"],[1,"(f) pay tort claims, in the manner authorized in the first paragraph of section 2672, as amended, of title 28, when such claims arise in foreign countries in connection with Department of State operations abroad;"],[1,"(g) obtain services as authorized by section 3109 of title 5 at a rate not to exceed the maximum rate payable for GS–18 under section 5332 of such title 5;"],[1,"(h) directly procure goods and services in the United States or abroad, solely for use by United States Foreign Service posts abroad when the Secretary of State, in accordance with guidelines established in consultation with the Administrator of General Services, determines that use of the Federal Acquisition Service or otherwise applicable Federal goods and services acquisition authority would not meet emergency overseas security requirements determined necessary by the Secretary, taking into account overseas delivery, installation, maintenance, or replacement requirements, except that the authority granted by this paragraph shall cease to be effective when the amendment made by section 2711 of the Competition in Contracting Act of 1984 takes effect and thereafter procurement by the Secretary of State for the purposes described in this paragraph shall be in accordance with section 3304(a)(2) of title 41;"],[1,"(i) pay obligations assumed in Germany on or after June 5, 1945;"],[1,"(j) provide telecommunications services;"],[1,"(k) provide maximum physical security in Government-owned and leased properties and vehicles abroad;"],[1,"(l) purchase special purpose passenger motor vehicles without regard to any price limitation otherwise established by law;"],[1,"(m) pay obligations arising under international agreements, conventions, and binational contracts to the extent otherwise authorized by law;"],[1,"(n) exercise the authority provided in subsection (c), upon the request of the Secretary of Defense or the head of any other department or agency of the United States, to enter into personal service contracts with individuals to perform services in support of the Department of Defense or such other department or agency, as the case may be; and"],[1,"(o) make administrative corrections or adjustments to an employee's pay, allowances, or differentials, resulting from mistakes or retroactive personnel actions, as well as provide back pay and other categories of payments under section 5596 of title 5, as part of the settlement or compromise of administrative claims or grievances filed against the Department."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/2669?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2669. Printing and binding outside continental United States; settlement and payment of claims by foreign governments; employment of aliens; official functions and courtesies; purchase of uniforms; payment of tort claims; payment of assumed obligations in Germany; telecommunications services; security; special purpose passenger motor vehicles; pay obligations arising under international conventions or contracts; personal service contracts","tname":"Foreign Relations and Intercourse","by":{"2":"25","3":"16"}},{"t":"usc","label":"22 U.S.C. § 2669-1","url":"https://www.law.cornell.edu/uscode/text/22/2669-1","by":{"2":"25"}},{"t":"reg","label":"8 C.F.R. § 287.10","url":"https://www.ecfr.gov/current/title-8/section-287.10","by":{"2":"31"}},{"t":"reg","label":"Exec. Order No. 13,732, § 2(b)(ii), 81 Fed. Reg. 44,486","url":"https://www.govinfo.gov/link/fr/81/44486","by":{"2":"24"}},{"t":"case","label":"Arar v. Ashcroft","cite":"585 F.3d 559","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/585/559/","by":{"3":"5"}},{"t":"case","label":"Baker v. Carr","cite":"369 U.S. 186","y":1962,"id":"1960/6","sc":1,"sum":"The Court found that redistricting issues present justiciable questions, and in which the Court reframed its political question doctrine.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Collins v. Virginia","cite":"138 S. Ct. 1663","y":2018,"id":"2017/16-1027","sc":1,"sum":"The Court held that a police officer cannot, under the Fourth Amendment, enter private property in order to conduct a warrantless search of a vehicle parked a few feet from the house.","sumSrc":"Oyez","by":{"3":"21"}},{"t":"case","label":"El-Shifa Pharm. Indus. Co. v. United States","cite":"607 F.3d 836","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/607/836/","by":{"3":"4"}},{"t":"case","label":"Hamdi v. Rumsfeld","cite":"542 U.S. 507","y":2004,"id":"2003/03-6696","sc":1,"sum":"The Court held that individuals held in military confinement by the national government have a right, under the Fifth Amendment, to appeal that confinement in front of a neutral decision-making body.","sumSrc":"Oyez","by":{"3":"4"}},{"t":"case","label":"Harbury v. Hayden","cite":"522 F.3d 413","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/522/413/","op":1,"by":{"3":"15"}},{"t":"case","label":"Helvering v. Mitchell","cite":"303 U.S. 391","y":1938,"id":"scdb/1937-140","sc":1,"sum":"That an acquittal of a charge of wilful attempt to evade, under § 146 (b), does not bar assessment and collection of the 50% addition prescribed by § 293 (b)..397 et seq. The doctrine of res judicata is inapplicable because of the difference in quantum of proof in civil and criminal cases; the acquittal was merely an adjudication that the proof was not sufficient to overcome all reasonable doubt of guilt. P. 397. …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"7"}},{"t":"case","label":"Hinderlider v. La Plata River & Cherry Creek Ditch Co.","cite":"304 U.S. 92","y":1938,"id":"scdb/1937-042","sc":1,"sum":"1. The water of an interstate stream, used beneficially in each of the two States through which it flows, must be equitably apportioned between the two. P. 101. The claim that on interstate streams the upper State has such ownership or control of the whole stream as entitles it to divert all the.water, regardless of any injury or prejudice to the lower State, has been consistently denied by this Court. P. 102.--'. …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"21"}},{"t":"case","label":"Jesner v. Arab Bank, PLC","cite":"138 S. Ct. 1386","y":2018,"id":"2017/16-499","sc":1,"op":5,"sum":"The Court held that the Alien Tort Statute does not permit lawsuits against corporations.","sumSrc":"Oyez","by":{"3":"14, 21"}},{"t":"case","label":"Leal Garcia v. Texas","cite":"564 U.S. 940","y":2011,"id":"scdb/2010-085","sc":1,"sum":"No. The Due Process Clause does not bar a State from carrying out a lawful judgment because of unenacted legislation that might someday allow a collateral attack, and a stay was unwarranted given Medellin v. Texas.","sumSrc":"AI-generated brief","by":{"3":"7"}},{"t":"case","label":"Rasul v. Myers","cite":"563 F.3d 527","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/563/527/","by":{"3":"4"}},{"t":"case","label":"Reid v. Covert","cite":"354 U.S. 1","y":1957,"id":"1955/701","sc":1,"sum":"Citizen spouses of members of the U.S. military abroad are not subject to the U.S. Code of Military Justice but are entitled to Fifth and Sixth Amendment protections","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"United States v. Spelar","cite":"338 U.S. 217","y":1949,"id":"scdb/1949-001","sc":1,"op":1,"sum":"The Federal Tort Claims Act, which is inapplicable by its terms to any claim \"arising in a foreign country,\" does not authorize an action against the United States for an allegedly wrongful death occurring at a Newfoundland air base under long-term lease from Great Britain to the United States and allegedly resulting from the negligent operation of the air base by the United States. VermilyaBrown Co. v. Connell, 335 …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"11"}},{"t":"case","label":"Weinberger v. Salfi","cite":"422 U.S. 749","y":1975,"id":"1974/74-214","sc":1,"sum":"After her husband of less than six months died, appellee widow filed applications for mother's Social Security insurance benefits for herself and child's insurance benefits for her daughter by a previous marriage, but the Social Security Administration (SSA), both initially and on reconsideration at the regional level, denied the applications on the basis of the duration-of-relationship requirements of the Social …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"19"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Clinton","cite":"566 U.S. 189","y":2012,"id":"2011/10-699","sc":1,"sum":"The Court held that a dispute over passport regulation was not a political issue and is thus liable for judicial review.","sumSrc":"Oyez","by":{"3":"4, 6"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(b)(1)"],"by":{"3":"11"}},{"t":"law","label":"Detainee Treatment Act (DTA), Pub. L. No. 109-148","url":"https://www.govinfo.gov/link/plaw/109/public/148","by":{"3":"12"}}]};